ALTER TABLE playback_progress ADD COLUMN last_sequence INTEGER NOT NULL DEFAULT 0;
CREATE TRIGGER learning_item_insert AFTER INSERT ON series_items BEGIN UPDATE series SET total_items=(SELECT COUNT(*) FROM series_items WHERE series_id=NEW.series_id),completed_items=(SELECT COUNT(*) FROM series_items i JOIN playback_progress p ON p.item_id=i.id WHERE i.series_id=NEW.series_id AND p.completed=1) WHERE id=NEW.series_id; END;
CREATE TRIGGER learning_item_delete AFTER DELETE ON series_items BEGIN UPDATE series SET total_items=(SELECT COUNT(*) FROM series_items WHERE series_id=OLD.series_id),completed_items=(SELECT COUNT(*) FROM series_items i JOIN playback_progress p ON p.item_id=i.id WHERE i.series_id=OLD.series_id AND p.completed=1) WHERE id=OLD.series_id; END;
CREATE TRIGGER learning_item_move AFTER UPDATE OF series_id ON series_items BEGIN UPDATE series SET total_items=(SELECT COUNT(*) FROM series_items WHERE series_id=OLD.series_id),completed_items=(SELECT COUNT(*) FROM series_items i JOIN playback_progress p ON p.item_id=i.id WHERE i.series_id=OLD.series_id AND p.completed=1) WHERE id=OLD.series_id;UPDATE series SET total_items=(SELECT COUNT(*) FROM series_items WHERE series_id=NEW.series_id),completed_items=(SELECT COUNT(*) FROM series_items i JOIN playback_progress p ON p.item_id=i.id WHERE i.series_id=NEW.series_id AND p.completed=1) WHERE id=NEW.series_id; END;
CREATE TRIGGER learning_progress_insert AFTER INSERT ON playback_progress BEGIN UPDATE series SET total_items=(SELECT COUNT(*) FROM series_items WHERE series_id=(SELECT series_id FROM series_items WHERE id=NEW.item_id)),completed_items=(SELECT COUNT(*) FROM series_items i JOIN playback_progress p ON p.item_id=i.id WHERE i.series_id=(SELECT series_id FROM series_items WHERE id=NEW.item_id) AND p.completed=1) WHERE id=(SELECT series_id FROM series_items WHERE id=NEW.item_id); END;
CREATE TRIGGER learning_progress_update AFTER UPDATE OF completed ON playback_progress BEGIN UPDATE series SET total_items=(SELECT COUNT(*) FROM series_items WHERE series_id=(SELECT series_id FROM series_items WHERE id=NEW.item_id)),completed_items=(SELECT COUNT(*) FROM series_items i JOIN playback_progress p ON p.item_id=i.id WHERE i.series_id=(SELECT series_id FROM series_items WHERE id=NEW.item_id) AND p.completed=1) WHERE id=(SELECT series_id FROM series_items WHERE id=NEW.item_id); END;
CREATE TRIGGER learning_progress_delete AFTER DELETE ON playback_progress BEGIN UPDATE series SET total_items=(SELECT COUNT(*) FROM series_items WHERE series_id=(SELECT series_id FROM series_items WHERE id=OLD.item_id)),completed_items=(SELECT COUNT(*) FROM series_items i JOIN playback_progress p ON p.item_id=i.id WHERE i.series_id=(SELECT series_id FROM series_items WHERE id=OLD.item_id) AND p.completed=1) WHERE id=(SELECT series_id FROM series_items WHERE id=OLD.item_id); END;
UPDATE series SET total_items=(SELECT COUNT(*) FROM series_items i WHERE i.series_id=series.id),completed_items=(SELECT COUNT(*) FROM series_items i JOIN playback_progress p ON p.item_id=i.id WHERE i.series_id=series.id AND p.completed=1);
UPDATE schema_version SET version=3;
